Lemma ev_lit0 : forall E z, edenot E (ELit z) = Z_to_bv 64 z.
Proof. intros; reflexivity. Qed.

Lemma ev_mul4_0 : forall E a x, edenot E a = Z_to_bv 64 x -> 0 <= x < 2 ^ 61 ->
  edenot E (EMd M_MUL (ELit 4) a) = Z_to_bv 64 (4 * x).
Proof.
  intros E a x Ha Hx. cbn [edenot]. rewrite Ha. rewrite w_mul by lia. reflexivity.
Qed.
